const curSpread = (W, bloom, moving) => (W.spread + (W.pel > 1 ? 0 : bloom)) * (moving && W.pel === 1 ? 1.7 : 1) + (moving && W.pel === 1 ? .015 : 0);
const RARITY = ['#b8bcc4', '#51cf66', '#4dabf7', '#cc5de8', '#ffc61a']; // серое → золотое
